3	import java.util.List;
4	import net.officefloor.web.HttpQueryParameter;
5	import net.officefloor.web.ObjectResponse;
6	
7	/**
8	 * GET /api/projects — list all projects (each with its client's name). With an optional
9	 * {@code ?clientId=<id>} it lists only the projects done for that client; with {@code ?tagId=<id>}
10	 * only the projects carrying that tag (the "filter by label" dropdown). Archived projects are
11	 * hidden unless {@code ?includeArchived=true} is passed (the "show archived" toggle).
12	 */
13	public class ProjectsGetLogic {
14	
15	    public void service(@HttpQueryParameter("clientId") String clientId,
16	            @HttpQueryParameter("tagId") String tagId,
17	            @HttpQueryParameter("includeArchived") String includeArchived,
