    private void seedProjectTags(Map<String, Object> fixture) {
        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
                    id(pt, "projectId"), id(pt, "tagId"));
